mapper.select:
SELECT base_date, base_time, nx, ny, category, obsr_value
FROM public.tb_ultra_srt_ncst
WHERE nx = #{nx} AND ny = #{ny}
  AND base_date = #{baseDate} AND base_time = #{baseTime}
  AND category = #{category}

SELECT base_date, base_time, nx, ny, category, obsr_value
FROM public.tb_ultra_srt_ncst
WHERE nx = #{nx} AND ny = #{ny}
  AND (base_date, base_time) = (
      SELECT base_date, base_time FROM public.tb_ultra_srt_ncst
      WHERE nx = #{nx} AND ny = #{ny}
      ORDER BY base_date DESC, base_time DESC LIMIT 1
  )
ORDER BY category
